#!/usr/bin/env python3
"""Compute ground truth for CSX-060_Q2."""

from __future__ import annotations

import json
import math
import re
import warnings
from datetime import date
from pathlib import Path
from statistics import mean

warnings.filterwarnings("ignore")
from pypdf import PdfReader


TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_ROOT = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / "CSX-060"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_001_Locked_package_evidence_report.pdf",
    "data/event_reports/event_reports_003_Locked_event_anchor_September_2024_Nepal_floods_and_landslides.json",
    "data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_006_CHIRPS_daily_event_accumulated_precipitation.json",
    "data/exposure_impact/exposure_impact_003_WorldPop_GP_100m_population_sum.json",
    "data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json",
    "data/remote_sensing/remote_sensing_005_Sentinel-1_GRD_VV_pre_post_change.json",
]

RUBRIC = {
    "total_points": 20,
    "criteria": [
        {
            "name": "Final label and diagnostic structure",
            "points": 4,
            "description": "Returns score_ledger, final_label, failed_primary_candidates, and computed_interpretation, with final_label equal to station_river_slope_joint_anchor.",
            "partial_credit": "Award 1 point for each required field that is present and usable; withhold the final-label point if the label is wrong.",
        },
        {
            "name": "Station rainfall calculations",
            "points": 4,
            "description": "Computes station maximum, weighted mean, max-to-mean ratio, station count, and rainfall-threshold shares correctly.",
            "partial_credit": "Award up to 4 points in proportion to the correctly computed station values within tolerance.",
        },
        {
            "name": "River exceedance calculations",
            "points": 3,
            "description": "Computes 5 of 7 historic river exceedances, share 0.714, and maximum exceedance 3.52 m.",
            "partial_credit": "Award 1.5 points for the correct exceedance share and 1.5 points for the correct maximum exceedance.",
        },
        {
            "name": "Record-station cluster calculations",
            "points": 3,
            "description": "Computes cluster count 16, density 16.0 per 1000 km2, and spacing 7.906 km.",
            "partial_credit": "Award 1 point for each correct cluster value within tolerance.",
        },
        {
            "name": "Secondary signal calculations",
            "points": 3,
            "description": "Computes gridded-to-station ratios, warning normalization, Sentinel-1 mean change, and AlphaEarth maximum.",
            "partial_credit": "Award up to 3 points for correctly computing most secondary values within tolerance.",
        },
        {
            "name": "Threshold logic",
            "points": 2,
            "description": "Marks station, river, and record-station tests as passing and gridded, warning-volume, and image-change tests as failing.",
            "partial_credit": "Award 1 point for the correct three passing tests and 1 point for the correct three failing tests.",
        },
        {
            "name": "Concise computed interpretation",
            "points": 1,
            "description": "Gives a one-sentence interpretation tied to the computed diagnostic without adding claims beyond the event diagnosis.",
            "partial_credit": "Award 0.5 points if the interpretation is directionally correct but too broad.",
        },
    ],
}


def read_json(rel_path: str) -> dict:
    return json.loads((PACKAGE_ROOT / rel_path).read_text(encoding="utf-8", errors="replace"))


def read_pdf_text(rel_path: str) -> str:
    reader = PdfReader(str(PACKAGE_ROOT / rel_path))
    return "\n".join(page.extract_text() or "" for page in reader.pages)


def normalized_text(text: str) -> str:
    return re.sub(r"\s+", " ", text).strip()


def require_match(pattern: str, text: str, flags: int = 0) -> re.Match[str]:
    match = re.search(pattern, text, flags)
    if not match:
        raise ValueError(f"Pattern not found: {pattern}")
    return match


def parse_int_text(value: str) -> int:
    return int(value.replace(",", ""))


def parse_precip_bins(report_text: str) -> list[tuple[float, float, int]]:
    text = normalized_text(report_text)
    patterns = [
        (50.0, 100.0, r"50 mm\s*.\s*100 mm\s+(\d+)"),
        (100.0, 200.0, r"100 mm\s*.\s*200 mm\s+(\d+)"),
        (200.0, 300.0, r"200 mm\s*.\s*300 mm\s+(\d+)"),
        (300.0, 400.0, r"300 mm\s*.\s*400 mm\s+(\d+)"),
        (400.0, 500.0, r"400 mm\s*.\s*500 mm\s+(\d+)"),
        (500.0, 600.0, r"More than 500 mm\s+(\d+)"),
    ]
    return [(low, high, int(require_match(pattern, text).group(1))) for low, high, pattern in patterns]


def parse_record_stations(report_text: str) -> list[tuple[str, str, float, float]]:
    rows: list[tuple[str, str, float, float]] = []
    row_pattern = re.compile(
        r"^\s*(\d+)\s+(.+?)\s+([A-Za-z][A-Za-z()]+)\s+([0-9.]+)\s+([0-9.]+)\s+\d{1,2}-[A-Za-z]{3}-\d{4}"
    )
    for line in report_text.splitlines():
        match = row_pattern.match(line)
        if not match:
            continue
        row_number = int(match.group(1))
        if 1 <= row_number <= 25:
            rows.append((match.group(2), match.group(3), float(match.group(4)), float(match.group(5))))
    if len(rows) != 25:
        raise ValueError(f"Expected 25 record-station rows, found {len(rows)}")
    return rows


def parse_river_gauge_rows(report_text: str) -> list[tuple[str, float, float]]:
    text = normalized_text(report_text)
    start = text.find("Table 4:")
    end = text.find("The flood verification result", start)
    if start < 0 or end < 0:
        raise ValueError("Could not isolate river gauge table")
    block = text[start:end]
    rows = re.findall(
        r"\b\d+\s+[0-9.]+\s+(.+?)\s+\d{1,2}-[A-Za-z]{3}-\d{4}\s+([0-9.]+)\s+([0-9.]+)(?=\s+\d+\s+[0-9.]+\s+|\s*$)",
        block,
    )
    if len(rows) != 7:
        raise ValueError(f"Expected 7 river gauge rows, found {len(rows)}")
    return [(name, float(historic), float(observed)) for name, historic, observed in rows]


def parse_report_scalar_metrics(report_text: str) -> dict[str, int | float]:
    text = normalized_text(report_text)
    sms_raw = require_match(r"SMS\s*-\s*([0-9,]+)", text).group(1)
    return {
        "max_3day_station_mm": float(
            require_match(r"Daman recorded the highest three-day accumulated precipitation of ([0-9.]+) mm", text).group(1)
        ),
        "record_cluster_area_km2": float(
            require_match(r"(\d+) of these record breaking stations were located within a small area of approximately ([0-9,]+) square kilometers", text).group(2)
        ),
        "record_cluster_count": int(
            require_match(r"(\d+) of these record breaking stations were located within a small area of approximately", text).group(1)
        ),
        "sms_alerts": parse_int_text(sms_raw),
    }


def round_float(value: float, digits: int = 3) -> float:
    return round(float(value), digits)


def inclusive_days(start_date: str, end_date: str) -> int:
    return (date.fromisoformat(end_date) - date.fromisoformat(start_date)).days + 1


def station_bin_metrics(precip_bins: list[tuple[float, float, int]]) -> dict:
    total = sum(count for _, _, count in precip_bins)
    weighted = sum(((low + high) / 2.0) * count for low, high, count in precip_bins) / total
    above_200 = sum(count for low, _, count in precip_bins if low >= 200.0)
    above_300 = sum(count for low, _, count in precip_bins if low >= 300.0)
    above_400 = sum(count for low, _, count in precip_bins if low >= 400.0)
    return {
        "three_day_station_count": total,
        "three_day_weighted_mean_mm": round_float(weighted),
        "stations_above_200mm": above_200,
        "stations_above_300mm": above_300,
        "stations_above_400mm": above_400,
        "three_day_share_above_200mm": round_float(above_200 / total),
        "three_day_share_above_300mm": round_float(above_300 / total),
        "three_day_share_above_400mm": round_float(above_400 / total),
    }


def record_station_metrics(rows: list[tuple[str, str, float, float]], cluster_count: int, cluster_area_km2: float) -> dict:
    current_values = [row[2] for row in rows]
    ratios = [row[2] / row[3] for row in rows]
    kathmandu_valley_districts = {"Kathmandu", "Lalitpur", "Bhaktapur"}
    return {
        "record_24h_station_count": len(rows),
        "record_24h_district_count": len({row[1] for row in rows}),
        "record_stations_in_kathmandu_valley": sum(1 for row in rows if row[1] in kathmandu_valley_districts),
        "record_stations_in_approx_1000km2": cluster_count,
        "record_station_density_per_1000km2": round_float(cluster_count / cluster_area_km2 * 1000.0),
        "approx_record_station_spacing_km": round_float(math.sqrt(cluster_area_km2 / cluster_count)),
        "max_24h_record_mm": round_float(max(current_values), 1),
        "mean_24h_record_mm": round_float(mean(current_values)),
        "max_record_ratio": round_float(max(ratios)),
        "largest_record_ratio_station": rows[ratios.index(max(ratios))][0],
    }


def river_metrics(river_gauge_rows: list[tuple[str, float, float]]) -> dict:
    exceedances = []
    for name, historic, observed in river_gauge_rows:
        exceedance = observed - historic
        ratio = observed / historic
        if observed > historic:
            exceedances.append((name, exceedance, ratio))
    max_by_m = max(exceedances, key=lambda item: item[1])
    max_by_ratio = max(exceedances, key=lambda item: item[2])
    return {
        "rivers_checked": len(river_gauge_rows),
        "rivers_above_historic_count": len(exceedances),
        "max_river_exceedance_m": round_float(max_by_m[1]),
        "max_river_exceedance_station": max_by_m[0],
        "max_river_level_ratio": round_float(max_by_ratio[2]),
        "max_river_level_ratio_station": max_by_ratio[0],
    }


def build_metrics() -> dict:
    report_text = read_pdf_text("data/event_reports/event_reports_001_Locked_package_evidence_report.pdf")
    report_scalars = parse_report_scalar_metrics(report_text)
    precip_bins = parse_precip_bins(report_text)
    record_station_rows = parse_record_stations(report_text)
    river_gauge_rows = parse_river_gauge_rows(report_text)

    event_meta = read_json("metadata/event.json")
    anchor = read_json("data/event_reports/event_reports_003_Locked_event_anchor_September_2024_Nepal_floods_and_landslides.json")
    era5 = read_json("data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json")
    gpm = read_json("data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json")
    chirps = read_json("data/physical_hazard/physical_hazard_006_CHIRPS_daily_event_accumulated_precipitation.json")
    worldpop = read_json("data/exposure_impact/exposure_impact_003_WorldPop_GP_100m_population_sum.json")
    alpha = read_json("data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json")
    s1 = read_json("data/remote_sensing/remote_sensing_005_Sentinel-1_GRD_VV_pre_post_change.json")

    station_bins = station_bin_metrics(precip_bins)
    record = record_station_metrics(
        record_station_rows,
        int(report_scalars["record_cluster_count"]),
        float(report_scalars["record_cluster_area_km2"]),
    )
    river = river_metrics(river_gauge_rows)
    gpm_event_max_mm = gpm["stats"]["gpm_event_precip_mm_max"]
    chirps_event_max_mm = chirps["stats"]["chirps_event_precip_mm_max"]
    era5_event_max_mm = era5["stats"]["precipitation_sum_mm_max"]
    worldpop_population = worldpop["population_sum"]["population"]

    metrics = {
        "event_name": event_meta["event_name"],
        "hazard_family": event_meta["hazard_family"],
        "start_date": anchor["temporal_window"]["start_date"],
        "end_date": anchor["temporal_window"]["end_date"],
        "event_window_days": inclusive_days(anchor["temporal_window"]["start_date"], anchor["temporal_window"]["end_date"]),
        "max_3day_station_mm": report_scalars["max_3day_station_mm"],
        **station_bins,
        **record,
        **river,
        "gpm_event_mean_mm": round_float(gpm["stats"]["gpm_event_precip_mm_mean"]),
        "gpm_event_max_mm": round_float(gpm_event_max_mm),
        "chirps_event_mean_mm": round_float(chirps["stats"]["chirps_event_precip_mm_mean"]),
        "chirps_event_max_mm": round_float(chirps_event_max_mm),
        "era5_land_precip_mean_mm": round_float(era5["stats"]["precipitation_sum_mm_mean"]),
        "era5_land_precip_max_mm": round_float(era5_event_max_mm),
        "station_max_to_weighted_mean_ratio": round_float(
            float(report_scalars["max_3day_station_mm"]) / station_bins["three_day_weighted_mean_mm"]
        ),
        "river_historic_exceedance_share": round_float(river["rivers_above_historic_count"] / river["rivers_checked"]),
        "gpm_max_share_of_station_max": round_float(gpm_event_max_mm / float(report_scalars["max_3day_station_mm"])),
        "chirps_max_share_of_station_max": round_float(chirps_event_max_mm / float(report_scalars["max_3day_station_mm"])),
        "era5_max_share_of_station_max": round_float(era5_event_max_mm / float(report_scalars["max_3day_station_mm"])),
        "worldpop_population_rounded": int(round(worldpop_population / 1000) * 1000),
        "sms_alerts": report_scalars["sms_alerts"],
        "sms_alerts_per_1000_worldpop": round_float(float(report_scalars["sms_alerts"]) / worldpop_population * 1000.0, 1),
        "sentinel1_pre_count": s1["counts"]["pre_count"],
        "sentinel1_post_count": s1["counts"]["post_count"],
        "sentinel1_vv_change_mean_db": round_float(s1["stats"]["s1_vv_post_minus_pre_db_mean"]),
        "sentinel1_vv_change_range_db": round_float(
            s1["stats"]["s1_vv_post_minus_pre_db_max"] - s1["stats"]["s1_vv_post_minus_pre_db_min"]
        ),
        "alphaearth_change_mean": round_float(alpha["stats"]["alphaearth_1_minus_cosine_mean"]),
        "alphaearth_change_max": round_float(alpha["stats"]["alphaearth_1_minus_cosine_max"]),
    }
    return metrics


def score_ledger(metrics: dict) -> dict:
    station_pass = (
        metrics["station_max_to_weighted_mean_ratio"] >= 2.0
        and metrics["three_day_share_above_200mm"] >= 0.50
        and metrics["three_day_station_count"] >= 150
    )
    river_pass = (
        metrics["river_historic_exceedance_share"] >= 0.60
        and metrics["max_river_exceedance_m"] >= 2.0
    )
    record_pass = (
        metrics["record_stations_in_approx_1000km2"] >= 15
        and metrics["record_station_density_per_1000km2"] >= 15
        and metrics["approx_record_station_spacing_km"] <= 8.5
    )
    gridded_pass = (
        metrics["gpm_max_share_of_station_max"] >= 0.50
        and max(
            metrics["gpm_max_share_of_station_max"],
            metrics["chirps_max_share_of_station_max"],
            metrics["era5_max_share_of_station_max"],
        )
        >= 0.50
    )
    warning_pass = metrics["sms_alerts_per_1000_worldpop"] >= 1000
    image_pass = (
        abs(metrics["sentinel1_vv_change_mean_db"]) >= 3.0
        and metrics["alphaearth_change_max"] >= 0.8
    )
    return {
        "station_rainfall_cluster": {
            "pass": station_pass,
            "supporting_values": {
                "station_max_to_weighted_mean_ratio": metrics["station_max_to_weighted_mean_ratio"],
                "three_day_share_above_200mm": metrics["three_day_share_above_200mm"],
                "three_day_station_count": metrics["three_day_station_count"],
            },
            "reason": "All three station-rainfall thresholds are met."
            if station_pass
            else "At least one station-rainfall threshold is not met.",
        },
        "river_historic_exceedance": {
            "pass": river_pass,
            "supporting_values": {
                "river_historic_exceedance_share": metrics["river_historic_exceedance_share"],
                "max_river_exceedance_m": metrics["max_river_exceedance_m"],
            },
            "reason": "Five of seven checked rivers exceeded historic levels, and the largest exceedance is above 2 m."
            if river_pass
            else "River exceedance share or maximum exceedance is below threshold.",
        },
        "record_station_cluster": {
            "pass": record_pass,
            "supporting_values": {
                "record_stations_in_approx_1000km2": metrics["record_stations_in_approx_1000km2"],
                "record_station_density_per_1000km2": metrics["record_station_density_per_1000km2"],
                "approx_record_station_spacing_km": metrics["approx_record_station_spacing_km"],
            },
            "reason": "The record-station cluster clears the count, density, and spacing thresholds."
            if record_pass
            else "The record-station cluster does not clear the count, density, and spacing thresholds together.",
        },
        "gridded_rainfall_primary": {
            "pass": gridded_pass,
            "supporting_values": {
                "gpm_max_share_of_station_max": metrics["gpm_max_share_of_station_max"],
                "chirps_max_share_of_station_max": metrics["chirps_max_share_of_station_max"],
                "era5_max_share_of_station_max": metrics["era5_max_share_of_station_max"],
            },
            "reason": "At least one gridded maximum reaches one half of the station maximum."
            if gridded_pass
            else "The gridded maxima are all below one half of the station maximum.",
        },
        "public_warning_volume_primary": {
            "pass": warning_pass,
            "supporting_values": {
                "sms_alerts_per_1000_worldpop": metrics["sms_alerts_per_1000_worldpop"],
            },
            "reason": "The normalized warning count reaches the threshold."
            if warning_pass
            else "The normalized warning count is below the 1000 per 1000 people threshold.",
        },
        "image_change_primary": {
            "pass": image_pass,
            "supporting_values": {
                "sentinel1_vv_change_mean_db": metrics["sentinel1_vv_change_mean_db"],
                "alphaearth_change_max": metrics["alphaearth_change_max"],
            },
            "reason": "The radar and embedding metrics both clear the primary-signal thresholds."
            if image_pass
            else "Neither the mean radar-change threshold nor the embedding-change threshold is met.",
        },
    }


def failed_primary_candidates(metrics: dict) -> list[dict]:
    return [
        {
            "test_id": "gridded_rainfall_primary",
            "deciding_value": {
                "gpm": metrics["gpm_max_share_of_station_max"],
                "chirps": metrics["chirps_max_share_of_station_max"],
                "era5_land": metrics["era5_max_share_of_station_max"],
            },
            "reason": "All gridded maxima are below one half of the station maximum.",
        },
        {
            "test_id": "public_warning_volume_primary",
            "deciding_value": metrics["sms_alerts_per_1000_worldpop"],
            "reason": "Warning volume per 1000 people is below the stated threshold.",
        },
        {
            "test_id": "image_change_primary",
            "deciding_value": {
                "sentinel1_vv_change_mean_db": metrics["sentinel1_vv_change_mean_db"],
                "alphaearth_change_max": metrics["alphaearth_change_max"],
            },
            "reason": "The radar and embedding changes both miss the primary-signal thresholds.",
        },
    ]


def main() -> None:
    metrics = build_metrics()
    ledger = score_ledger(metrics)
    final_label = (
        "station_river_slope_joint_anchor"
        if (
            ledger["station_rainfall_cluster"]["pass"]
            and ledger["river_historic_exceedance"]["pass"]
            and ledger["record_station_cluster"]["pass"]
            and not ledger["gridded_rainfall_primary"]["pass"]
            and not ledger["public_warning_volume_primary"]["pass"]
            and not ledger["image_change_primary"]["pass"]
        )
        else "mixed_or_secondary_anchor"
    )
    computed_interpretation = (
        "The event is best anchored by concentrated station rainfall, historic river exceedance, and a dense cluster of record rainfall stations rather than by gridded rainfall, warning volume, or image-change maxima."
        if final_label == "station_river_slope_joint_anchor"
        else "The event has a mixed or secondary-anchor pattern because the six threshold tests do not isolate the station-river-record cluster."
    )
    primary_gt = {
        "score_ledger": ledger,
        "final_label": final_label,
        "failed_primary_candidates": failed_primary_candidates(metrics),
        "computed_interpretation": computed_interpretation,
    }

    output = {
